import unreal, json
les = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
ues = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem)
original = ues.get_editor_world().get_path_name().split('.')[0]
if unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages(): raise RuntimeError('Dirty map; inspection deferred')
if not les.load_level('/Game/Levels/Game_Levels/Lvl_Forsaken_Castle'): raise RuntimeError('Map load failed')
rows = []
for a in unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors():
    if isinstance(a, unreal.LevelInstance):
        row = {'actor': a.get_actor_label()}
        try: row['world_asset'] = str(a.get_editor_property('world_asset'))
        except Exception as e: row['error'] = str(e)
        rows.append(row)
print(json.dumps(rows, indent=2))
if not unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages(): print('Returned:', les.load_level(original))
